import React, { useState, useEffect } from "react";

function AddToTripModal({ order, onClose, onSuccess, onCreateNewTrip }) {
  const [trips, setTrips] = useState([]);
  const [loading, setLoading] = useState(true);
  const [adding, setAdding] = useState(null);

  useEffect(() => {
    fetchActiveTrips();
  }, []);

  const fetchActiveTrips = async () => {
    setLoading(true);
    try {
      const response = await fetch("http://127.0.0.1:5000/api/trips");
      const data = await response.json();
      const active = data.filter(t =>
        t.status !== "Laskutettu" && t.status !== "Toimitettu"
      );
      setTrips(active);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleAddToTrip = async (tripId) => {
    setAdding(tripId);
    try {
      const response = await fetch(
        `http://127.0.0.1:5000/api/trips/${tripId}/orders/${order.id}`,
        { method: "POST" }
      );
      const data = await response.json();
      if (response.ok) {
        onSuccess();
      } else {
        alert(data.warnings
          ? data.warnings.join("\n")
          : data.error || "Virhe lisättäessä"
        );
      }
    } catch (err) {
      alert("Palvelinyhteys epäonnistui");
    } finally {
      setAdding(null);
    }
  };

  const getCapacityColor = (used, max) => {
    const pct = max > 0 ? (used / max) * 100 : 0;
    if (pct > 90) return "#ef4444";
    if (pct > 75) return "#f97316";
    return "#22c55e";
  };

  const STATUS_COLORS = {
    "Suunniteltu": "#3b82f6",
    "Vahvistettu": "#eab308",
    "Käynnissä": "#f97316",
  };

  return (
    <div style={{
      position: "fixed",
      inset: 0,
      background: "rgba(0,0,0,0.7)",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      zIndex: 9999
    }}>
      <div style={{
        background: "#1e293b",
        border: "1px solid #334155",
        borderRadius: "16px",
        padding: "32px",
        maxWidth: "600px",
        width: "90%",
        maxHeight: "80vh",
        overflow: "hidden",
        display: "flex",
        flexDirection: "column"
      }}>
        {/* Header */}
        <div style={{ marginBottom: "20px" }}>
          <h3 style={{ color: "#f97316", margin: "0 0 8px" }}>
            🚚 Lisää Order Tripille
          </h3>
          <div style={{
            background: "#0f172a",
            borderRadius: "8px",
            padding: "12px 16px"
          }}>
            <div style={{ color: "#f97316", fontWeight: "600", marginBottom: "4px" }}>
              {order.order_id}
            </div>
            <div style={{ color: "#cbd5e1", fontSize: "13px" }}>
              {order.consignor_name || "—"} → {order.consignee_name || "—"}
            </div>
            <div style={{ color: "#64748b", fontSize: "12px", marginTop: "2px" }}>
              {order.goods_description || "—"} · {order.weight} kg · {order.loading_meters} lm · {order.quantity} × {order.pallet_type}
            </div>
          </div>
        </div>

        {/* Trip lista */}
        <div style={{ flex: 1, overflowY: "auto", marginBottom: "16px" }}>
          {loading ? (
            <div style={{ color: "#94a3b8", textAlign: "center", padding: "24px" }}>
              Ladataan...
            </div>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: "8px" }}>
              {trips.length === 0 ? (
                <div style={{
                  color: "#64748b",
                  textAlign: "center",
                  padding: "24px",
                  border: "1px dashed #334155",
                  borderRadius: "8px"
                }}>
                  Ei aktiivisia trippejä.
                </div>
              ) : (
                trips.map(trip => {
                  const weightPct = trip.max_weight > 0
                    ? ((trip.capacity?.total_weight || 0) / trip.max_weight) * 100
                    : 0;
                  const lmPct = trip.max_loading_meters > 0
                    ? ((trip.capacity?.total_loading_meters || 0) / trip.max_loading_meters) * 100
                    : 0;

                  return (
                    <div
                      key={trip.id}
                      style={{
                        background: "#0f172a",
                        border: "1px solid #334155",
                        borderRadius: "8px",
                        padding: "14px 16px",
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                        gap: "16px"
                      }}
                    >
                      <div style={{ flex: 1 }}>
                        <div style={{
                          display: "flex",
                          alignItems: "center",
                          gap: "10px",
                          marginBottom: "6px"
                        }}>
                          <span style={{ color: "#f97316", fontWeight: "600" }}>
                            {trip.trip_id}
                          </span>
                          <span style={{
                            background: STATUS_COLORS[trip.status] || "#475569",
                            color: "#fff",
                            padding: "2px 8px",
                            borderRadius: "10px",
                            fontSize: "11px",
                            fontWeight: "600"
                          }}>
                            {trip.status}
                          </span>
                        </div>
                        <div style={{ color: "#94a3b8", fontSize: "12px", marginBottom: "8px" }}>
                          {trip.first_pickup_country} {trip.first_pickup_city} → {trip.trip_end_country} {trip.trip_end_city}
                          {trip.carrier_name ? ` · ${trip.carrier_name}` : ""}
                        </div>

                        {/* Kapasiteettipalkit */}
                        <div style={{ display: "flex", gap: "16px" }}>
                          <div style={{ flex: 1 }}>
                            <div style={{
                              display: "flex",
                              justifyContent: "space-between",
                              fontSize: "11px",
                              color: "#64748b",
                              marginBottom: "2px"
                            }}>
                              <span>Paino</span>
                              <span>{trip.capacity?.total_weight || 0} / {trip.max_weight || 24000} kg</span>
                            </div>
                            <div style={{
                              height: "6px",
                              background: "#334155",
                              borderRadius: "3px",
                              overflow: "hidden"
                            }}>
                              <div style={{
                                height: "100%",
                                width: `${Math.min(weightPct, 100)}%`,
                                background: getCapacityColor(
                                  trip.capacity?.total_weight || 0,
                                  trip.max_weight || 24000
                                ),
                                borderRadius: "3px"
                              }} />
                            </div>
                          </div>
                          <div style={{ flex: 1 }}>
                            <div style={{
                              display: "flex",
                              justifyContent: "space-between",
                              fontSize: "11px",
                              color: "#64748b",
                              marginBottom: "2px"
                            }}>
                              <span>Lastausmetrit</span>
                              <span>{trip.capacity?.total_loading_meters || 0} / {trip.max_loading_meters || 13.6} lm</span>
                            </div>
                            <div style={{
                              height: "6px",
                              background: "#334155",
                              borderRadius: "3px",
                              overflow: "hidden"
                            }}>
                              <div style={{
                                height: "100%",
                                width: `${Math.min(lmPct, 100)}%`,
                                background: getCapacityColor(
                                  trip.capacity?.total_loading_meters || 0,
                                  trip.max_loading_meters || 13.6
                                ),
                                borderRadius: "3px"
                              }} />
                            </div>
                          </div>
                        </div>
                      </div>

                      {/* Lisää-nappi */}
                      <button
                        onClick={() => handleAddToTrip(trip.id)}
                        disabled={adding === trip.id}
                        style={{
                          background: adding === trip.id ? "#475569" : "#f97316",
                          color: "#fff",
                          border: "none",
                          padding: "8px 16px",
                          borderRadius: "6px",
                          cursor: adding === trip.id ? "not-allowed" : "pointer",
                          fontSize: "13px",
                          fontWeight: "600",
                          whiteSpace: "nowrap"
                        }}
                      >
                        {adding === trip.id ? "..." : "Lisää →"}
                      </button>
                    </div>
                  );
                })
              )}
            </div>
          )}
        </div>

        {/* Footer */}
        <div style={{
          display: "flex",
          gap: "8px",
          borderTop: "1px solid #334155",
          paddingTop: "16px"
        }}>
          <button
            onClick={onCreateNewTrip}
            style={{
              flex: 1,
              background: "#22c55e",
              color: "#fff",
              border: "none",
              padding: "10px",
              borderRadius: "6px",
              cursor: "pointer",
              fontWeight: "600",
              fontSize: "13px"
            }}
          >
            + Luo uusi Trip tästä Orderista
          </button>
          <button
            onClick={onClose}
            style={{
              background: "transparent",
              color: "#94a3b8",
              border: "1px solid #334155",
              padding: "10px 20px",
              borderRadius: "6px",
              cursor: "pointer",
              fontSize: "13px"
            }}
          >
            Peruuta
          </button>
        </div>
      </div>
    </div>
  );
}

export default AddToTripModal;
